                r.u.switch_s.cases[i].value = s->u.switch_s.cases[i].value;
                r.u.switch_s.cases[i].high_value = s->u.switch_s.cases[i].high_value;
                r.u.switch_s.cases[i].is_range = s->u.switch_s.cases[i].is_range;
